import{_ as t,o,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇886｜超脱者与法律·超脱者与共生宪法的关系","description":"","frontmatter":{"title":"篇886｜超脱者与法律·超脱者与共生宪法的关系","no":886,"module":4,"tags":["超脱","法律","共生宪法","宪法地位","根本大法"],"related":["40-共生宪法总纲","03-共生文明宪章","883-超脱者的法律地位","763-宪章超多元落地"]},"headers":[],"relativePath":"zh/886_模块4-超脱者与法律-共生宪法的关系.md","filePath":"zh/886_模块4-超脱者与法律-共生宪法的关系.md"}'),l={name:"zh/886_模块4-超脱者与法律-共生宪法的关系.md"};function i(h,a,n,s,u,d){return o(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="篇886-超脱者与法律·超脱者与共生宪法的关系" tabindex="-1">篇886｜超脱者与法律·超脱者与共生宪法的关系 <a class="header-anchor" href="#篇886-超脱者与法律·超脱者与共生宪法的关系" aria-label="Permalink to &quot;篇886｜超脱者与法律·超脱者与共生宪法的关系&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档40、03、883、763</p></blockquote><h2 id="引言-共生宪法不是超脱者写的——超脱者也在宪法之下" tabindex="-1">引言：共生宪法不是超脱者写的——超脱者也在宪法之下 <a class="header-anchor" href="#引言-共生宪法不是超脱者写的——超脱者也在宪法之下" aria-label="Permalink to &quot;引言：共生宪法不是超脱者写的——超脱者也在宪法之下&quot;">​</a></h2><p>共生宪法是锚点共生文明的根本大法，一切法律、规则、公约都从它派生。旧世界的大帝往往是&quot;宪父&quot;——他制定根本大法，他解释根本大法，他也可以修改根本大法。衡元宙必须明确：<strong>共生宪法不是超脱者写的，超脱者也在宪法之下。</strong> 本篇讲超脱者与共生宪法的根本关系。</p><p>六大顶层公理在此刻同时压阵：万族共和公理是宪法合法性的来源——宪法是万族的公约，不是某个人的恩赐；反掠夺主义公理是宪法的核心内容；集体升维公理是宪法的目的；因果自律公理要求宪法执行可追溯；法则优先公理要求宪法本身法则级自洽、可无限迭代；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、共生宪法的合法性来源" tabindex="-1">一、共生宪法的合法性来源 <a class="header-anchor" href="#一、共生宪法的合法性来源" aria-label="Permalink to &quot;一、共生宪法的合法性来源&quot;">​</a></h2><p>共生宪法（文档40、03）的合法性不来自某个超脱者的&quot;钦定&quot;，而来自：</p><ol><li><strong>万族共识</strong>：万族五大谱系代表通过锚点议事会共同制定</li><li><strong>历史实践</strong>：从锚点觉醒纪元（文档72）到万族共和成立（文档77），宪法是在长期共生实践中逐步成型的</li><li><strong>阿赖耶验证</strong>：宪法条款经过阿赖耶网络+多层监督的因果验证，确认不产生文明倒退</li><li><strong>持续修订</strong>：宪法不是一成不变的，修订程序由议事会主导</li></ol><p>超脱者在宪法制定过程中做了什么？他提供了技术支持——法则自洽性检查、因果影响评估、技术可行性论证。但他没有&quot;写下&quot;宪法，他不能&quot;钦定&quot;宪法。</p><h2 id="二、超脱者在宪法下的三重身份" tabindex="-1">二、超脱者在宪法下的三重身份 <a class="header-anchor" href="#二、超脱者在宪法下的三重身份" aria-label="Permalink to &quot;二、超脱者在宪法下的三重身份&quot;">​</a></h2><h3 id="身份一-宪法的遵守者" tabindex="-1">身份一：宪法的遵守者 <a class="header-anchor" href="#身份一-宪法的遵守者" aria-label="Permalink to &quot;身份一：宪法的遵守者&quot;">​</a></h3><p>超脱者必须遵守共生宪法。宪法规定的一切权利义务，超脱者一体遵循。他不能以&quot;我是超脱者&quot;为由不遵守宪法条款。</p><h3 id="身份二-宪法的守护者" tabindex="-1">身份二：宪法的守护者 <a class="header-anchor" href="#身份二-宪法的守护者" aria-label="Permalink to &quot;身份二：宪法的守护者&quot;">​</a></h3><p>超脱者有责任维护宪法不被破坏。如果有人（包括万族内部的野心家）试图推翻宪法、架空议事会、废除监督机制——超脱者必须制止。</p><h3 id="身份三-宪法的修订参与者" tabindex="-1">身份三：宪法的修订参与者 <a class="header-anchor" href="#身份三-宪法的修订参与者" aria-label="Permalink to &quot;身份三：宪法的修订参与者&quot;">​</a></h3><p>超脱者可以通过正常立法程序参与宪法修订——提案、讨论、投票，他只有一票。他不能单方面修改宪法。</p><p>三重身份合起来：<strong>超脱者在宪法之下，但他也维护宪法。他不是宪法的主人，他是宪法的公民和守护者。</strong></p><h2 id="三、超脱者不能做的三件事" tabindex="-1">三、超脱者不能做的三件事 <a class="header-anchor" href="#三、超脱者不能做的三件事" aria-label="Permalink to &quot;三、超脱者不能做的三件事&quot;">​</a></h2><h3 id="_1-不能解释宪法为自己服务" tabindex="-1">1. 不能解释宪法为自己服务 <a class="header-anchor" href="#_1-不能解释宪法为自己服务" aria-label="Permalink to &quot;1. 不能解释宪法为自己服务&quot;">​</a></h3><p>宪法的解释权属于共生法院宪法庭，不属于超脱者。超脱者不能说&quot;我理解宪法是这样的&quot;来为自己的行为找依据。</p><h3 id="_2-不能暂停宪法" tabindex="-1">2. 不能暂停宪法 <a class="header-anchor" href="#_2-不能暂停宪法" aria-label="Permalink to &quot;2. 不能暂停宪法&quot;">​</a></h3><p>紧急状态下，某些法律可以临时调整——但宪法不能暂停。超脱者不能以&quot;情况紧急&quot;为由停止宪法效力。</p><h3 id="_3-不能绕过宪法立法" tabindex="-1">3. 不能绕过宪法立法 <a class="header-anchor" href="#_3-不能绕过宪法立法" aria-label="Permalink to &quot;3. 不能绕过宪法立法&quot;">​</a></h3><p>任何规则变更必须符合宪法框架。超脱者不能绕开宪法&quot;临时立法&quot;——他提的法案如果违宪，议事会也不能通过。</p><h2 id="四、宪法修订与超脱者的关系" tabindex="-1">四、宪法修订与超脱者的关系 <a class="header-anchor" href="#四、宪法修订与超脱者的关系" aria-label="Permalink to &quot;四、宪法修订与超脱者的关系&quot;">​</a></h2><p>宪法是可以修订的——文明在发展，宪法也需要迭代。但修订程序非常严格：</p><ol><li>宪法修订提案必须由至少一定比例的万族代表联署</li><li>提案必须经过至少两个完整审议周期</li><li>修订必须经万族公投（超多元尺度的全民投票）</li><li>修订后必须通过阿赖耶因果验证</li></ol><p>超脱者可以参与这个过程——他可以提案、可以技术说明、可以投票。但他不能单方面修订宪法，也不能利用声望推动&quot;快速修订&quot;。</p><p>宪法是活的——它随文明发展而迭代。但迭代必须走程序：议事会提案、万族公投、阿赖耶验证。超脱者不能&quot;觉得宪法过时了&quot;就自己改。宪法的权威来自它是万族的共识，不来自任何一个超脱者的认可。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：宪法是万族共识的结晶，超脱者不需要&quot;重新发明轮子&quot;</li><li><strong>反掠夺</strong>：宪法本身就是反掠夺的根本大法，超脱者在宪法之下意味着他也不能掠夺</li><li><strong>唐罗上限对比</strong>：唐罗就是宪法——他说的就是根本大法；衡元宙把唐罗放到宪法之下，他也不能违宪</li><li><strong>万族全覆盖</strong>：宪法适用于万族五大谱系一切生灵，包括超脱者</li><li><strong>超多元全开放</strong>：宪法全文、修订历史、公投结果全部通过无私道全网开放</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>共生宪法不是超脱者写的，超脱者也在宪法之下。他是宪法的遵守者、守护者、修订参与者——但不是宪法的主人。他不能解释宪法为自己服务，不能暂停宪法，不能绕过宪法立法。当最强的人也要遵守根本大法时，文明才真正有了根。这，才是超脱者与共生宪法关系的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./40-共生宪法总纲.html">40-共生宪法总纲</a> · <a href="./03-共生文明宪章.html">03-共生文明宪章</a> · <a href="./883_模块4-超脱者与法律-总论.html">883-超脱者的法律地位</a> · <a href="./763_模块4-超多元级文明工程-宪章超多元落地.html">763-宪章超多元落地</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',36)])])}const c=t(l,[["render",i]]);export{_ as __pageData,c as default};
